// whether the time of receiving wl_surface.commit with a new buffer
// attached, applying the wl_surface state, wl_surface.frame callback
// trigger, presentation, or any other point in the compositor cycle
// is used to measure the frame or field times. There is no support
// for detecting missed or late frames/fields/buffers either, and
// there is no support whatsoever for cooperating with interlaced
// compositor output.
//
// The composited image quality resulting from the use of interlaced
// buffers is explicitly undefined. A compositor may use elaborate
// hardware features or software to deinterlace and create progressive
// output frames from a sequence of interlaced input buffers, or it
// may produce substandard image quality. However, compositors that
// cannot guarantee reasonable image quality in all cases are recommended
// to just reject all interlaced buffers.
//
// Any argument errors, including non-positive width or height,
// mismatch between the number of planes and the format, bad
// format, bad offset or stride, may be indicated by fatal protocol
// errors: INCOMPLETE, INVALID_FORMAT, INVALID_DIMENSIONS,
// OUT_OF_BOUNDS.
//
// Dmabuf import errors in the server that are not obvious client
// bugs are returned via the 'failed' event as non-fatal. This
// allows attempting dmabuf sharing and falling back in the client
// if it fails.
//
// This request can be sent only once in the object's lifetime, after
// which the only legal request is destroy. This object should be
// destroyed after issuing a 'create' request. Attempting to use this
// object after issuing 'create' raises the ALREADY_USED protocol error.
//
// It is not mandatory to issue 'create'. If a client wants to
// cancel the buffer creation, it can just destroy this object.
func (self *ZwpLinuxBufferParamsV1) Create(width int32, height int32, format uint32, flags ZwpLinuxBufferParamsV1Flags) {
	msg := self.Begin(2)
	msg.Int(width)
	msg.Int(height)
	msg.Uint(format)
	msg.Uint(uint32(flags))
	msg.Done()
}

// CreateImmed sends the zwp_linux_buffer_params_v1.create_immed request: immediately create a wl_buffer from the given dmabufs.
//
// This asks for immediate creation of a wl_buffer by importing the
// added dmabufs.
//
// In case of import success, no event is sent from the server, and the
// wl_buffer is ready to be used by the client.
//
// Upon import failure, either of the following may happen, as seen fit
// by the implementation:
// - the client is terminated with one of the following fatal protocol
// errors:
// - INCOMPLETE, INVALID_FORMAT, INVALID_DIMENSIONS, OUT_OF_BOUNDS,
// in case of argument errors such as mismatch between the number
// of planes and the format, bad format, non-positive width or
// height, or bad offset or stride.
// - INVALID_WL_BUFFER, in case the cause for failure is unknown or
// platform specific.
// - the server creates an invalid wl_buffer, marks it as failed and
// sends a 'failed' event to the client. The result of using this
// invalid wl_buffer as an argument in any request by the client is
// defined by the compositor implementation.
//
// This takes the same arguments as a 'create' request, and obeys the
// same restrictions.
//
// Since version 2.
// The new object has the same version as the receiver.
func (self *ZwpLinuxBufferParamsV1) CreateImmed(width int32, height int32, format uint32, flags ZwpLinuxBufferParamsV1Flags) *WlBuffer {
	msg := self.Begin(3)
	proxy_ := &WlBuffer{}
	msg.NewObject(proxy_, self.Version())
	msg.Int(width)
	msg.Int(height)
	msg.Uint(format)
	msg.Uint(uint32(flags))
	msg.Done()
	return proxy_
}

// SetSamplingDevice sends the zwp_linux_buffer_params_v1.set_sampling_device request: set the target device of the wl_buffer.
//
// Set the device the compositor should import the dmabufs to for sampling
// in the next create or create_immed request.
//
// To avoid race conditions when the compositor removes a device from the
// tranches, it is not a protocol error if the device hasn't been advertised
// by the compositor in a tranche with the sampling flag, but the import is
// likely to fail in that case.
//
// If the client doesn't know a suitable target device, it shouldn't set one,
// and the compositor should attempt import on all devices it supports.
//
// If the array is too small to contain a dev_t or larger than required, the
// invalid_dev_t_size error will be emitted.
//
// Since version 6.
func (self *ZwpLinuxBufferParamsV1) SetSamplingDevice(device []byte) {
	msg := self.Begin(4)
	msg.Array(device)
	msg.Done()
}

// ZwpLinuxDmabufFeedbackV1 is the client proxy of the zwp_linux_dmabuf_feedback_v1 interface: dmabuf feedback.
//
// This object advertises dmabuf parameters feedback. This includes the
// preferred devices and the supported formats/modifiers.
//
// The parameters are sent once when this object is created and whenever they
// change. The done event is always sent once after all parameters have been
// sent. When a single parameter changes, all parameters are re-sent by the
// compositor.
//
// Compositors can re-send the parameters when the current client buffer
// allocations are sub-optimal. Compositors should not re-send the
// parameters if re-allocating the buffers would not result in a more optimal
// configuration. In particular, compositors should avoid sending the exact
// same parameters multiple times in a row.
//
// The tranche_target_device and tranche_formats events are grouped by
// tranches of preference. For each tranche, a tranche_target_device, one
// tranche_flags and one or more tranche_formats events are sent, followed
// by a tranche_done event finishing the list. The tranches are sent in
// descending order of preference. All formats and modifiers in the same
// tranche have the same preference.
//
// To send parameters, the compositor sends one main_device event (unless
// the client bound version 6 or above), tranches (each consisting of one
// tranche_target_device event, one tranche_flags event, tranche_formats
// events and then a tranche_done event), then one done event.
//
// With version 6 and above, the compositor must always advertise at least
// one tranche with the sampling flag set.
//
// Highest version known to these bindings: 6.
type ZwpLinuxDmabufFeedbackV1 struct {
	wire.Proxy
	onDone                func(ZwpLinuxDmabufFeedbackV1DoneEvent)
	onFormatTable         func(ZwpLinuxDmabufFeedbackV1FormatTableEvent)
	onMainDevice          func(ZwpLinuxDmabufFeedbackV1MainDeviceEvent)
	onTrancheDone         func(ZwpLinuxDmabufFeedbackV1TrancheDoneEvent)
	onTrancheTargetDevice func(ZwpLinuxDmabufFeedbackV1TrancheTargetDeviceEvent)
	onTrancheFormats      func(ZwpLinuxDmabufFeedbackV1TrancheFormatsEvent)
	onTrancheFlags        func(ZwpLinuxDmabufFeedbackV1TrancheFlagsEvent)
}

// ZwpLinuxDmabufFeedbackV1InterfaceName is the protocol name of ZwpLinuxDmabufFeedbackV1, as advertised by wl_registry.global.
const ZwpLinuxDmabufFeedbackV1InterfaceName = "zwp_linux_dmabuf_feedback_v1"

// ZwpLinuxDmabufFeedbackV1Version is the highest version of zwp_linux_dmabuf_feedback_v1 known to these bindings.
